  "struct_hints": [
    {
      "offset": 32,
      "meaning": "event context field used as the abort check target and as a zero/non-zero scheduling condition"
    },
    {
      "offset": 68,
      "meaning": "dispatch callback pointer called with the event descriptor for immediate host delivery"
    },
    {
      "offset": 72,
